function mergeFeeds(lists, cursor = Infinity, limit = 20) {
  const pos = lists.map(() => 0), page = [];
  while (page.length < limit) {
    let best = -1;
    for (let i = 0; i < lists.length; i++) {
      while (pos[i] < lists[i].length && lists[i][pos[i]] >= cursor) pos[i]++;
      if (pos[i] < lists[i].length && (best === -1 || lists[i][pos[i]] > lists[best][pos[best]])) best = i;
    }
    if (best === -1) break;
    page.push(lists[best][pos[best]++]);
  }
  return { page, nextCursor: page.length ? page[page.length - 1] : null };
}
```
`O(limit × k)`; use a heap when k is large.
